import json
r=json.load(open('../research.json'));q=r['candidates'][0]['question']
claim_id='C-prepare-vballot-preservation'
ss=['S-recovery','S-wire','S-send','S-receive','S-rpc','S-messages']
def grounding(derivation,applicability,ids=ss):return dict(source_ids=ids,expectation_ids=['S-recovery','S-messages','S-rpc'],derivation=derivation,applicability=applicability,unresolved=[],conflicts=[],alternatives=[])
claim=dict(id=claim_id,kind='obligation',concern='implementation_semantics',description='For a valid PrepareReply produced by an EPaxos acceptor and successfully transported through the registered peer RPC codec into a fresh message for the same acceptor/instance, the decoded VBallot must equal the producer-reported value ballot. The transport must preserve the support provenance that the recovery selector compares.',source_ids=ss,scope=dict(description='PrepareReply value-ballot preservation at the acceptor-to-recovery RPC boundary in static-membership crash-fault EPaxos.',assumptions=['Unmodified producer and consumer codecs from the same captured implementation','Valid in-memory acceptor state established by protocol handlers; complete noncorrupt delivery to a fresh registered reply object'],excluded=['Whole-cluster agreement or liveness consequence','Crash-restart persistence','Malformed or Byzantine message handling']),pending=[],grounding=grounding('S-recovery handlePrepare copies inst.vbal into PrepareReply.VBallot, and handlePrepareReply compares this field to rank prior support. S-messages declares the distinct Ballot and VBallot fields. S-rpc/S-send/S-receive implement object transfer by Marshal then New/Unmarshal, with no alternative provenance field or reconstruction before the consumer. Preserving that value is a necessary local caller/codec responsibility, derived from the composed producer-consumer interface, not from codec behavior or a protocol name. The local equality claim does not require an observed wrong consensus decision.','Valid same-version message transfer; newly allocated receiver object.'))
bindings=[]
for bid,mid,symbol,a,b,desc in [('BD-prepare-producer','S-recovery','handlePrepare',1171,1202,'Producer reports vbal independently of raised promise'),('BD-prepare-codec','S-wire','Marshal',153,208,'PrepareReply encoder is the message preservation boundary'),('BD-prepare-decode','S-wire','Unmarshal',210,252,'PrepareReply decoder populates fresh receiver object'),('BD-prepare-consumer','S-recovery','handlePrepareReply',1204,1314,'Recovery selection consumes VBallot as support provenance')]:
 bindings.append(dict(id=bid,material_id=mid,symbol=symbol,start_line=a,end_line=b,description=desc,pending=[],associations=[dict(claim_id=claim_id,source_ids=ss,rationale='This source supplies the stated part of the producer/codec/consumer preservation relation.')]))
legal=grounding('The harness allocates only eight instance slots per row instead of MAX_INSTANCE and reproduces constructor defaults used by these handlers, including -1 prefixes, Thrifty=true, F=1, Dreply=true and Durable=false. No executor/network goroutines run. Each owner calls startPhase1 for its first row instance, as handlePropose does; bytes actually emitted by bcastPreAccept/SendMsg are decoded and delivered to its preferred acceptor. A distinct coordinator calls startRecoveryForInstance on the target and its emitted Prepare is decoded/delivered. The investigated entry is valid Prepare handling, independent of how an executor learned the target; the harness does not claim to reproduce a timed recovery trigger. Serial handler calls choose one admissible schedule with each selected message delivered once. Buffers replace transport only; handlers and codecs remain unchanged. All sampled fields have one synchronous owner. Fresh objects use RPC.Get(code).Obj.New() exactly as the listener. Unselected outgoing messages remain pending in buffers; no requirement is inferred for them.','N=3,F=1; original owner 0 or 1; target instance 0; distinct acceptor and coordinator; valid noncorrupt messages; no crashes, background execution or clocks.',['S-init','S-members','S-phase1','S-bcast','S-ballot','S-recovery','S-defaults','S-send','S-receive','S-wire','S-rpc'])
plan=dict(description='For C-prepare-vballot-preservation, establish an acceptor value through an actual owner PreAccept broadcast, generate a higher Prepare with actual recovery entry, let handlePrepare emit bytes, then decode through fresh registered PrepareReply and compare VBallot to sampled producer state. Owner zero and owner one are preselected independent cases; message payload/ballot diagnostics must complete before result emission.',claim_id=claim_id,binding_ids=[b['id'] for b in bindings],harness=dict(kind='go_test',source='',files={},description='Synchronous bounded replicas with actual handlers and peer codecs; buffer-backed SendMsg captures emitted bytes.',semantic_changes=['Bound instance allocation and omit automatic networking/timers/executor startup for local handler isolation.','Buffered writers replace peer sockets; the driver selects and synchronously dispatches valid emitted messages once.','Emit prerequisite and result JSON after synchronous handler/codec completion; no protocol implementation edits.'],prerequisites=[dict(alias='produced',event='prepare_produced',conditions=[])],legality=legal),monitors=[dict(id='M-prepare-vballot',checker_id='P-prepare-vballot',event='prepare_decoded',binding_ids=[b['id'] for b in bindings],admission_alias='produced',grounding=grounding('The prerequisite samples inst.vbal after handlePrepare, whose producer copies exactly that field into the outgoing reply. The result samples reply.VBallot after successful decode into New(). Fields are synchronous with no concurrent writers. Identity is scenario plus actual decoded acceptor/row/instance; compared value is not a correlation filter.','Each independently selected case reaching prepare_produced owes one decode result.'))],observable_properties=[dict(checker_id='P-prepare-vballot',kind='event_assertion',trigger=dict(field='event',op='eq',value='prepare_decoded'),assertion=dict(field='vballot',op='eq',reference='produced.expected_vballot'),identity_fields=['scenario','acceptor','replica','instance'],description='Decoded value ballot equals the producer-side instance value ballot for the same PrepareReply.')],uncertainties=['Does not execute handlePrepareReply or assert a selected decision or application result.','Does not simulate the executor timer/history which requested recovery; the local valid-message transport obligation is independent of that trigger.'])
json.dump(plan,open('prepare_wire_plan.json','w'),indent=2)
sub=dict(action='check',rationale='Fix the local support-provenance preservation responsibility and execute actual producer/codec paths; do not infer cluster safety from the comparison.',candidate=dict(action='obligation',candidate_id=r['candidates'][0]['id'],rationale='Producer and consumer jointly ground the local preservation duty; execution can resolve the codec discrepancy without an invented protocol history.',question=q,obligation=claim,bindings=bindings),plan_path='prepare_wire_plan.json',harness_path='prepare_wire_test.go')
json.dump(sub,open('wire_submission.json','w'),indent=2)
